def find_conflicts(bookings):
    conflicts = []
    for i in range(len(bookings)):
        for j in range(i + 1, len(bookings)):
            if overlap(bookings[i], bookings[j]):
                conflicts.append((i, j))
    return conflicts

def total_amount(orders, rates):
    index = {r.currency: r.value for r in rates}      # константное число валют
    return sum(o.amount * index[o.currency] for o in orders)

